repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('pia', 35), ('noor', 14), ('noor', 46), ('mia', 19), ('mia', 11), ('omar', 37)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.accounts.py:
"""Accounts of donations. Rate lookups are billed, so each account remembers its charge."""
import rates


class DonationAccount:
    entries = []

    def __init__(self, name):
        self.name = name
        self._charge = None

    def add(self, donation):
        """Add one donation to this account."""
        self.entries.append(donation)
        self._charge = None

    def charge(self):
        """Return this account's charge: pounds times the rate for each donation's donor.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.pounds * rates.rate_for(x.donor) for x in self.entries)
        return self._charge


def largest_pounds(donations):
    """Return the largest pounds, or None when there are no donations."""
    values = [x.pounds for x in donations]
    return max(values) if values else None


def describe_donation(donation):
    """Return a one-line description of a donation."""
    return "%s: %s" % (donation.donor, donation.pounds)
